classdef (Abstract) ControlledTerm < openminds.base.ControlledTerm
%ControlledTerm Abstract base class for metadata types of the controlled terms module

%   This class was auto-generated by the openMINDS pipeline

    properties
        % Enter one sentence for defining this term.
        definition (1,1) string

        % Enter a short text describing this term.
        description (1,1) string

        % Controlled term originating from a defined terminology.
        name (1,1) string

        % Enter all internationalized resource identifiers (IRIs) pointing to cross-references to external databases or registries that are equivalent to this term (e.g., Wikidata). Do not repeat the preferred cross-reference.
        otherCrossReference (1,:) string ...
            {mustBeMinLength(otherCrossReference, 1), mustBeListOfUniqueItems(otherCrossReference)}

        % Enter all internationalized resource identifiers (IRIs) pointing to ontology entries that are equivalent to this term (e.g., UBERON). Do not repeat the preferred ontology identifier.
        otherOntologyIdentifier (1,:) string ...
            {mustBeMinLength(otherOntologyIdentifier, 1), mustBeListOfUniqueItems(otherOntologyIdentifier)}

        % Enter the internationalized resource identifier (IRI) pointing to the preferred cross-reference to an external database or registry (e.g., KnowledgeSpace).
        preferredCrossReference (1,1) string

        % Enter the internationalized resource identifier (IRI) pointing to the preferred ontological term (e.g., InterLex).
        preferredOntologyIdentifier (1,1) string

        % Enter one or several synonyms (including abbreviations) for this controlled term.
        synonym (1,:) string ...
            {mustBeMinLength(synonym, 1), mustBeListOfUniqueItems(synonym)}
    end

    methods
        function obj = ControlledTerm(instanceSpec, name, value)
            % Accept any name-value pairs, as openminds.Node does, so that a
            % subclass can forward properties this class does not declare.
            % instanceSpec is not validated here because a controlled term
            % accepts a name, a file path or a struct, unlike a Node.
            arguments
                instanceSpec = []
            end
            arguments (Repeating)
                name (1,1) string
                value
            end

            propValues = struct();
            for i = 1:numel(name)
                propValues.(name{i}) = value{i};
            end

            obj = obj.initializeControlledTerm(instanceSpec, propValues);
        end
    end
end
